@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap');

:root {
  --f2b-blue: var(--brand-primary,#3b82f6);
  --f2b-blue-dark: color-mix(in srgb, var(--brand-primary,#116cc4) 88%, #000);
  --f2b-charcoal: #202124;
  --f2b-ink: #22272b;
  --f2b-muted: #5c6570;
  --f2b-border: #dfe4e8;
  --f2b-page: #f5f7f8;
  --f2b-white: #fff;
}

html, body, button, input, select, textarea {
  font-family: 'Poppins', sans-serif !important;
  letter-spacing: .01em;
}
body { color: var(--f2b-ink); background: var(--f2b-page); font-size: 14px; line-height: 1.55; }
h1, h2, h3, h4, .metric-value, .sign-in-card h1 { font-family: 'Poppins', sans-serif !important; letter-spacing: -.025em; }
h1 { font-size: clamp(30px, 3vw, 40px) !important; line-height: 1.15 !important; font-weight: 800 !important; }
h2 { font-size: 22px !important; line-height: 1.25 !important; font-weight: 750 !important; }
h3 { font-size: 17px !important; line-height: 1.35 !important; font-weight: 700 !important; }
.muted, .page-heading .muted, .welcome-row .muted { color: var(--f2b-muted) !important; font-size: 15px !important; line-height: 1.65 !important; }
.eyebrow { color: color-mix(in srgb, var(--brand-primary,#176fbd) 88%, #000) !important; font-size: 11px !important; letter-spacing: .08em !important; font-weight: 800 !important; line-height: 1.5 !important; }
.app-shell { background: var(--f2b-page); }
.sidebar { background: var(--f2b-charcoal) !important; border-color: #34373b !important; }
.sidebar-brand b { color: #fff !important; font-size: 14px !important; letter-spacing: .08em !important; }
.sidebar-brand span { color: #c3c8cd !important; font-size: 10px !important; letter-spacing: .12em !important; }
.brand-mark { background: color-mix(in srgb, var(--brand-primary,#eaf5ff) 8%, #fff) !important; color: var(--f2b-blue) !important; border: 2px solid color-mix(in srgb, var(--brand-primary,#b8ddff) 15%, #fff) !important; font-family: 'Poppins', sans-serif !important; font-weight: 900 !important; }
.brand-mark::before { content: "◉"; margin-right: 3px; font-size: .78em; }
.nav-label { color: #aeb5bd !important; font-size: 11px !important; font-weight: 800 !important; letter-spacing: .1em !important; }
.nav-item { color: #e5e8eb !important; font-size: 13px !important; min-height: 42px !important; border-radius: 8px !important; }
.nav-item:hover { background: #30343a !important; }
.nav-item.active { color: #fff !important; background: var(--f2b-blue) !important; box-shadow: 0 5px 14px #1681e344 !important; }
.nav-icon { width: 25px !important; font-size: 17px !important; }
.client-nav-item { color: #eef1f4 !important; font-size: 13px !important; min-height: 38px; }
.sidebar-empty { color: #c4c9cf !important; font-size: 12px !important; line-height: 1.65 !important; }
.workspace-switch { background: #2e3237 !important; border-color: #44484d !important; color: #fff !important; }
.workspace-switch b { color: #fff !important; font-size: 13px !important; }
.workspace-switch small { color: #c7cbd0 !important; font-size: 11px !important; }
.help-card { background: #2c3238 !important; border-color: #454b52 !important; }
.help-card b { color: #fff !important; font-size: 13px !important; }
.help-card p { color: #d2d6da !important; font-size: 12px !important; line-height: 1.6 !important; }
.profile-row b { color: #fff !important; font-size: 13px !important; }
.profile-row small { color: #c5cbd0 !important; font-size: 11px !important; }
.main-area { background: var(--f2b-page) !important; }
.topbar { background: #fff !important; border-color: var(--f2b-border) !important; min-height: 58px !important; }
.breadcrumbs, .breadcrumbs b, .breadcrumbs span { font-size: 13px !important; }
.page-content { max-width: 1500px; }
.panel, .metric-card, .empty-state, .client-detail, .client-list-card, .team-card, .permission-table { border-color: var(--f2b-border) !important; box-shadow: 0 2px 8px #192b3a08 !important; }
.metric-card { min-height: 125px !important; padding: 18px !important; }
.metric-top > span:first-child { color: var(--f2b-muted) !important; font-size: 13px !important; font-weight: 650; }
.metric-icon { font-size: 17px !important; color: var(--f2b-blue) !important; background: color-mix(in srgb, var(--brand-primary,#e8f3ff) 8%, #fff) !important; }
.metric-value { color: var(--f2b-charcoal) !important; font-size: 29px !important; font-weight: 800 !important; }
.metric-card small, .table-sub, .service-chip small, .file-row small { color: var(--f2b-muted) !important; font-size: 12px !important; line-height: 1.5 !important; }
.primary-button { background: var(--f2b-blue) !important; border-color: var(--f2b-blue) !important; color: #fff !important; font-size: 13px !important; min-height: 42px; border-radius: 8px !important; box-shadow: 0 3px 8px color-mix(in srgb,var(--brand-primary,#3b82f6) 17%,transparent) !important; }
.primary-button:hover { background: var(--f2b-blue-dark) !important; border-color: var(--f2b-blue-dark) !important; }
.secondary-button, .text-button, .icon-button, .upload-button { font-size: 13px !important; }
.text-button { color: var(--f2b-blue-dark) !important; font-weight: 700 !important; }
.task-info b, .client-card-name b, .table-panel td b, .team-card h3 { color: var(--f2b-charcoal) !important; font-size: 13px !important; }
.task-info small, .client-card-name small, .table-panel td, .week-switch, .service-label, .chat-copy span, .workroom-head p, .note-card p { color: var(--f2b-muted) !important; font-size: 12px !important; line-height: 1.6 !important; }
.table-panel th { color: #46505a !important; font-size: 11px !important; letter-spacing: .04em !important; }
.table-panel td { font-size: 12px !important; }
.field { color: #303840 !important; font-size: 13px !important; }
.field input, .field select, .field textarea, .chat-link-form input, .service-form-row input { color: #252a30 !important; font-size: 14px !important; min-height: 42px; }
.modal-head h2 { color: var(--f2b-charcoal) !important; }
.modal { border-top: 5px solid var(--f2b-blue); }
.empty-state h2 { color: var(--f2b-charcoal) !important; }
.empty-state p, .empty-line span, .empty-note { color: var(--f2b-muted) !important; font-size: 14px !important; line-height: 1.7 !important; }
.empty-icon { color: var(--f2b-blue-dark) !important; background: color-mix(in srgb, var(--brand-primary,#e5f3ff) 8%, #fff) !important; border-radius: 12px !important; }
.welcome-visual { background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--brand-primary,#dceeff) 8%, #fff), #f5f8fb 70%) !important; }
.welcome-card { background: var(--f2b-charcoal) !important; border-color: #17191b !important; }
.welcome-visual { background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--brand-primary,#263847) 75%, #000), #202124 72%) !important; }
.welcome-copy h2 { color: #fff !important; }
.welcome-copy p:not(.eyebrow), .welcome-copy small { color: #e0e4e8 !important; }
.orbit { border-color: color-mix(in srgb,var(--brand-primary,#3b82f6) 33%,transparent) !important; }
.welcome-logo { color: #fff !important; background: var(--f2b-blue) !important; box-shadow: 0 12px 32px color-mix(in srgb,var(--brand-primary,#3b82f6) 33%,transparent) !important; }
.welcome-logo span { color: color-mix(in srgb, var(--brand-primary,#d9efff) 8%, #fff) !important; }
.welcome-copy h2 { color: #fff !important; }
.welcome-copy p:not(.eyebrow), .welcome-copy small { color: #e0e4e8 !important; font-size: 14px !important; line-height: 1.7 !important; }
.service-dot { background: var(--f2b-blue) !important; }
.bar-fill { background: var(--f2b-blue) !important; }
.bar-track { background: #e9edf1 !important; }
.service-bar-row b { color: var(--f2b-charcoal) !important; font-size: 12px !important; }
.quick-row button { min-height: 68px; font-size: 13px !important; }
.quick-row button b { color: var(--f2b-charcoal) !important; font-size: 13px !important; }
.quick-row button small { color: var(--f2b-muted) !important; font-size: 12px !important; }
.chat-connection { border-color: color-mix(in srgb, var(--brand-primary,#cae4fa) 12%, #fff) !important; background: #f0f8ff !important; }
.chat-glyph, .chat-connection .coming-pill { color: var(--f2b-blue-dark) !important; background: color-mix(in srgb, var(--brand-primary,#dceeff) 8%, #fff) !important; }
.section-title h3, .workroom-head h3 { color: var(--f2b-charcoal) !important; }
.status-pill { font-size: 11px !important; }
.priority { font-size: 11px !important; }
.task-row, .note-card, .file-row, .vault-card { border-color: var(--f2b-border) !important; }
.timer-start, .timer-stop, .stop-button { font-size: 12px !important; min-height: 38px; }
.active-timer-banner { border-color: var(--brand-primary,#b8dcfa) !important; background: color-mix(in srgb, var(--brand-primary,#eff8ff) 8%, #fff) !important; }
.active-timer-banner b, .active-timer-banner strong { color: color-mix(in srgb, var(--brand-primary,#155f9e) 88%, #000) !important; }
.chart-total { padding: 8px 11px; border-radius: 7px; color: color-mix(in srgb, var(--brand-primary,#145d9b) 88%, #000); background: color-mix(in srgb, var(--brand-primary,#e8f4ff) 8%, #fff); font-size: 12px; font-weight: 700; }
.weekly-chart { margin: 16px 0; padding: 20px; }
.chart-bars { height: 210px; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); align-items: end; gap: 14px; padding: 12px 6px 0; border-bottom: 1px solid #dfe5ea; background: repeating-linear-gradient(to top, transparent 0, transparent 47px, #e9edf1 48px, transparent 49px); }
.chart-day { height: 100%; display: grid; grid-template-rows: 22px 1fr 25px; justify-items: center; align-items: end; gap: 5px; color: #4c5660; font-size: 12px; }
.chart-hour { color: #4a5662; font-size: 11px; font-weight: 700; }
.chart-column { height: 100%; width: min(46px, 80%); display: flex; align-items: end; }
.chart-bar { width: 100%; min-height: 3px; background: linear-gradient(180deg, var(--brand-primary,#4da6f5), var(--brand-primary,#1879d1)); border-radius: 7px 7px 2px 2px; box-shadow: 0 4px 8px color-mix(in srgb,var(--brand-primary,#3b82f6) 13%,transparent); }
.chart-day b { align-self: center; font-size: 12px; }
.chart-caption { margin-top: 13px; color: var(--f2b-muted); font-size: 12px; }
.security-callout { display: flex; align-items: flex-start; gap: 12px; margin: 12px 0 18px; padding: 14px; border: 1px solid color-mix(in srgb, var(--brand-primary,#c6dff4) 14%, #fff); border-radius: 9px; background: #f1f8ff; color: var(--f2b-ink); }
.security-callout > span:first-child { font-size: 22px; }
.security-callout b { font-size: 13px; }
.security-callout p { margin: 4px 0 0; color: var(--f2b-muted); font-size: 13px; line-height: 1.6; }
.security-callout > div { flex: 1; }
.form-error { color: #a13d30 !important; background: #fff3f1; border-radius: 7px; padding: 10px 12px; font-size: 13px !important; }
.vault-actions { display: flex; gap: 8px; }
.vault-banner { align-items: center; }
.vault-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.vault-card { padding: 18px; border: 1px solid var(--f2b-border); border-radius: 10px; background: white; box-shadow: 0 3px 12px #13283a09; }
.vault-card-top { display: flex; justify-content: space-between; align-items: center; }
.vault-icon { font-size: 23px; }
.vault-card h2 { margin: 12px 0 3px; color: var(--f2b-charcoal); }
.vault-client { color: var(--f2b-muted); font-size: 13px; }
.vault-url { display: inline-block; margin: 3px 0 12px; color: var(--f2b-blue-dark); font-size: 13px; font-weight: 700; }
.vault-secret { display: grid; gap: 4px; padding: 12px; background: color-mix(in srgb, var(--brand-primary,#f4f7f9) 8%, #fff); border-radius: 8px; overflow-wrap: anywhere; }
.vault-secret small { margin-top: 5px; color: #65717c; font-size: 10px; font-weight: 800; letter-spacing: .08em; }
.vault-secret b { color: #252a30; font-size: 13px; }
.vault-notes { margin: 10px 0 0; color: var(--f2b-muted); font-size: 13px; line-height: 1.6; }
.file-head { margin-top: 22px; }
.upload-button { display: inline-flex; align-items: center; cursor: pointer; }
.file-list { display: grid; gap: 8px; }
.file-row { display: flex; align-items: center; gap: 11px; padding: 12px; border: 1px solid var(--f2b-border); border-radius: 8px; background: #fff; }
.file-row > span { font-size: 21px; }
.file-row > div { flex: 1; min-width: 0; }
.file-row b { display: block; overflow-wrap: anywhere; font-size: 13px; }
.file-row a { white-space: nowrap; }
.full-field { grid-column: 1 / -1; }
.security-callout ~ .form-grid + .form-error { margin-top: 12px; }
.toast { background: var(--f2b-charcoal) !important; font-size: 13px !important; }
.error-banner { font-size: 13px !important; }
:focus-visible { outline: 3px solid var(--brand-primary,#63b1ff) !important; outline-offset: 3px !important; }
@media (max-width: 760px) {
  .sidebar { background: var(--f2b-charcoal) !important; }
  .sidebar nav { scrollbar-color: #858c93 #202124; }
  .nav-item { min-height: 42px !important; }
  .nav-icon { display: inline-block !important; width: auto !important; margin-right: 5px; font-size: 15px !important; }
  .page-heading { gap: 14px; }
  .page-heading .muted { max-width: 48ch; }
  .chart-bars { height: 175px; gap: 5px; }
  .chart-day b { font-size: 11px; }
  .chart-hour { font-size: 10px; }
  .vault-grid { grid-template-columns: 1fr; }
  .vault-banner { align-items: flex-start; flex-wrap: wrap; }
  .vault-banner .status-pill { margin-left: 34px; }
  .vault-actions { flex-wrap: wrap; justify-content: flex-end; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

/* Readable dark mode and consistent Poppins typography */
*, *::before, *::after { font-family: 'Poppins', sans-serif !important; }
body:has(.app-shell.dark-mode) { background:#222124 !important; }
.app-shell.dark-mode .main-area,.app-shell.dark-mode .page-content { background:#222124 !important; }
.app-shell.dark-mode .topbar { background:#1e252b !important; border-color:#343e46 !important; }
.app-shell.dark-mode .modal { background:#202a31 !important; color:color-mix(in srgb, var(--brand-primary,#edf3f6) 8%, #fff) !important; border-color:#3c4850 !important; }
.app-shell.dark-mode .modal h2 { color:color-mix(in srgb, var(--brand-primary,#f3f7f9) 8%, #fff) !important; }
.app-shell.dark-mode .modal .eyebrow { color:var(--brand-primary,#63b5ff) !important; }
.app-shell.dark-mode .modal .field,.app-shell.dark-mode .modal .field > span,.app-shell.dark-mode .modal .service-form-head,.app-shell.dark-mode .modal .service-form-row { color:#e3ebef !important; }
.app-shell.dark-mode .modal .field input,.app-shell.dark-mode .modal .field select,.app-shell.dark-mode .modal .field textarea,.app-shell.dark-mode .modal .service-form-row input { background:#26323a !important; color:color-mix(in srgb, var(--brand-primary,#f2f6f8) 8%, #fff) !important; border-color:#52616b !important; color-scheme:dark; }
.app-shell.dark-mode .modal .field input::placeholder,.app-shell.dark-mode .modal .field textarea::placeholder { color:#b0bdc5 !important; opacity:1; }
.app-shell.dark-mode .modal .field select option { background:#26323a !important; color:color-mix(in srgb, var(--brand-primary,#f2f6f8) 8%, #fff) !important; }
.app-shell.dark-mode .modal .field span i,.app-shell.dark-mode .modal .form-hint,.app-shell.dark-mode .modal .invite-note p { color:#b8c4cb !important; }
.app-shell.dark-mode .modal .modal-actions { border-color:#45525b !important; }
.app-shell.dark-mode .modal .secondary-button { background:#2a3740 !important; color:color-mix(in srgb, var(--brand-primary,#e8eff3) 8%, #fff) !important; border-color:#53616a !important; }
.app-shell.dark-mode .modal .security-callout,.app-shell.dark-mode .modal .invite-note { background:#25343d !important; border-color:#40525e !important; color:#e3ebef !important; }
.app-shell.dark-mode .modal .security-callout p { color:#b8c4cb !important; }

/* Dark mode uses white text across the full workspace for clear readability. */
body:has(.app-shell.dark-mode),
body:has(.app-shell.dark-mode) :is(*, #f2b-white-text-override):not(.marketing-live-page):not(.marketing-live-page *) { color: #fff !important; }
body:has(.app-shell.dark-mode) :is(input, textarea, #f2b-white-text-override)::placeholder { color: #fff !important; opacity: 1; }
body:has(.app-shell.dark-mode) { color-scheme: dark; }
/* The global dark-mode white-text rule also reaches the completion banner. */
body:has(.app-shell.dark-mode) .confetti-message { background: #222124 !important; border: 1px solid #545258 !important; color: #fff !important; }

/* Dark theme: F2B charcoal surfaces sit against a lighter charcoal canvas. */
.app-shell.dark-mode {
  --dark-bg: #2b2a2d;
  --dark-panel: #222124;
  --dark-panel-2: #29282b;
  --dark-border: #3a393d;
}
body:has(.app-shell.dark-mode) { background: #2b2a2d !important; }
.app-shell.dark-mode .main-area,
.app-shell.dark-mode .page-content { background: #2b2a2d !important; }
.app-shell.dark-mode .sidebar,
.app-shell.dark-mode .topbar,
.app-shell.dark-mode .panel,
.app-shell.dark-mode .metric-card,
.app-shell.dark-mode .empty-state,
.app-shell.dark-mode .client-detail,
.app-shell.dark-mode .client-list-card,
.app-shell.dark-mode .team-card,
.app-shell.dark-mode .permission-table,
.app-shell.dark-mode .pipeline-toolbar,
.app-shell.dark-mode .pipeline-card,
.app-shell.dark-mode .table-panel,
.app-shell.dark-mode .welcome-card,
.app-shell.dark-mode .quick-row > button,
.app-shell.dark-mode .active-timer-banner,
.app-shell.dark-mode .modal,
.app-shell.dark-mode .finance-panel {
  background: #222124 !important;
  border-color: #3a393d !important;
}
.app-shell.dark-mode .pipeline-column,
.app-shell.dark-mode .service-chip,
.app-shell.dark-mode .client-stats,
.app-shell.dark-mode .chat-connection,
.app-shell.dark-mode .team-access-card,
.app-shell.dark-mode .profit-note,
.app-shell.dark-mode .distribution-panel,
.app-shell.dark-mode .service-bar-row,
.app-shell.dark-mode .field input,
.app-shell.dark-mode .field select,
.app-shell.dark-mode .field textarea,
.app-shell.dark-mode .chat-link-form input,
.app-shell.dark-mode .inline-select,
.app-shell.dark-mode .theme-toggle,
.app-shell.dark-mode .finance-summary > div {
  background: #29282b !important;
  border-color: #3a393d !important;
}
.app-shell.dark-mode .welcome-visual { background: radial-gradient(ellipse at center, #302f33 0, #28272a 55%, #222124 100%) !important; }

/* Dark-mode client file states must keep white text on dark surfaces. */
.app-shell.dark-mode .form-error {
  color: #fff !important;
  background: #3a2525 !important;
  border: 1px solid #704343 !important;
  border-radius: 7px;
}
.app-shell.dark-mode .empty-note {
  color: #fff !important;
  background: #222124 !important;
  border: 1px dashed #3a393d !important;
  border-radius: 8px;
}
.app-shell.dark-mode .file-row {
  color: #fff !important;
  background: #222124 !important;
  border-color: #3a393d !important;
}
.workspace-icon { width: 38px !important; height: 38px !important; flex: 0 0 38px; display: block; object-fit: cover; border-radius: 50% !important; border: 1px solid #d9dadd; background: #fff !important; }
.client-head-actions { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }
.service-chat-list { display:grid; gap:8px; margin:12px 0 26px; }
.service-chat-row { display:grid; grid-template-columns:32px minmax(130px, 190px) minmax(180px, 1fr) auto auto; align-items:center; gap:10px; padding:9px 12px; border:1px solid var(--f2b-border); border-radius:12px; background:#fff; }
.service-chat-icon { display:grid; place-items:center; width:30px; height:30px; border-radius:9px; background:color-mix(in srgb, var(--brand-primary,#e8f3ff) 8%, #fff); }
.service-chat-row input { min-width:0; width:100%; min-height:38px; padding:8px 11px; border:1px solid var(--f2b-border); border-radius:8px; background:#fff; color:var(--f2b-ink); }
.app-shell.dark-mode .service-chat-row { background:#252c32; border-color:#3f4a52; }
.app-shell.dark-mode .service-chat-icon { background:#303b45; }
.app-shell.dark-mode .service-chat-row input { background:#26323a; border-color:#52616b; color:#fff; color-scheme:dark; }
@media (max-width:760px) { .service-chat-row { grid-template-columns:30px 1fr auto; }.service-chat-row input { grid-column:1 / -1; grid-row:2; }.service-chat-row .text-button { grid-column:3; grid-row:1; } }
.client-logo-control { grid-column: 1 / -1; }
.client-logo-control .field { margin: 0; }
.client-logo-preview { display: flex; align-items: center; gap: 12px; margin-top: 8px; }
.client-logo-preview img { width: 58px; height: 58px; padding: 5px; object-fit: contain; border-radius: 9px; background: #fff; border: 1px solid #d8d8dc; }
.client-avatar.has-logo,.client-dot.has-logo { overflow: hidden; padding: 3px; background: #f4f4f5 !important; }
.client-avatar.has-logo img,.client-dot.has-logo img { width: 100%; height: 100%; object-fit: contain; border-radius: inherit; }
.task-client-mark { display: inline-grid; place-items: center; width: 21px; height: 21px; min-width: 21px; overflow: hidden; border-radius: 6px; color: #fff; font-size: 8px; font-weight: 800; }
.task-client-mark img { width: 100%; height: 100%; padding: 2px; object-fit: contain; background: #f4f4f5; border-radius: inherit; }
.pipeline-client { display: flex; align-items: center; gap: 6px; }
