.chess-confetti { position:absolute; inset:0; overflow:hidden; border-radius:inherit; pointer-events:none; }
.chess-confetti i { position:absolute; top:-12px; left:var(--x); width:7px; height:12px; border-radius:2px; background:#ffd34d; opacity:0; animation:chess-confetti-fall 1.55s ease-out var(--delay) forwards; }
