.app-shell .crm-kanban > .crm-stage, .app-shell .pipeline-board > .pipeline-column { border: 2px solid var(--stage-color, #94a3b8) !important; background: color-mix(in srgb, var(--stage-color, #94a3b8) 6%, var(--stage-base)) !important; }
