.card-drop-shadow-slot, .app-shell.dark-mode .card-drop-shadow-slot { border: 2px dashed var(--stage-color, var(--brand-primary,#3b82f6)); border-radius: 15px; background: color-mix(in srgb, var(--stage-color, var(--brand-primary,#3b82f6)) 16%, transparent); box-shadow: inset 0 6px 18px rgba(0,0,0,.28), 0 8px 20px rgba(0,0,0,.22); margin: 2px 0; }
