.chess-fx-banner.check { background:linear-gradient(135deg,#ef4444,#f97316); animation:chess-banner-check 1.5s cubic-bezier(.2,.9,.3,1.2) both; }
@keyframes chess-banner-pop { 0% { opacity:0; transform:scale(.4); } 18% { opacity:1; transform:scale(1.08); } 30% { transform:scale(1); } 80% { opacity:1; } 100% { opacity:0; transform:scale(1.15) translateY(-14px); } }
@keyframes chess-banner-check { 0% { opacity:0; transform:scale(.5) rotate(-4deg); } 14% { opacity:1; transform:scale(1.12) rotate(2deg); } 24% { transform:translateX(-8px); } 34% { transform:translateX(8px); } 44% { transform:translateX(-4px) scale(1); } 56% { transform:translateX(0); } 85% { opacity:1; } 100% { opacity:0; transform:scale(1.1); } }
.chess-board-wrap.fx-start .chess-board { animation:chess-board-in .7s cubic-bezier(.2,.9,.3,1) both; }
.chess-board-wrap.fx-start .chess-square { animation:chess-square-in .5s ease both; }
.chess-board-wrap.fx-start .chess-square .chess-piece-svg { animation:chess-piece-drop .6s cubic-bezier(.3,1.4,.5,1) both; animation-delay:.25s; }
.chess-board-wrap.fx-start .chess-square:nth-child(8n+1) { animation-delay:.00s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+2) { animation-delay:.03s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+3) { animation-delay:.06s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+4) { animation-delay:.09s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+5) { animation-delay:.12s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+6) { animation-delay:.15s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n+7) { animation-delay:.18s; } .chess-board-wrap.fx-start .chess-square:nth-child(8n) { animation-delay:.21s; }
@keyframes chess-board-in { from { opacity:0; transform:perspective(900px) rotateX(14deg) scale(.92); } to { opacity:1; transform:none; } }
@keyframes chess-square-in { from { opacity:0; } to { opacity:1; } }
@keyframes chess-piece-drop { from { opacity:0; transform:translateY(-70%) scale(1.25); } to { opacity:1; transform:none; } }
.chess-end-overlay { position:fixed; inset:0; z-index:9999; display:grid; place-items:center; background:rgba(0,0,0,.62); backdrop-filter:blur(3px); animation:chess-end-fade .35s ease both; overflow:hidden; }
