.chess-end-overlay.win .chess-end-card { border-color:#22c55e; box-shadow:0 0 0 6px rgba(34,197,94,.18),0 30px 80px rgba(0,0,0,.6); }
.chess-end-overlay.loss .chess-end-card { border-color:#ef4444; animation:chess-end-card .7s cubic-bezier(.2,1.2,.3,1) both,chess-end-shake .6s .6s ease; }
