/* Secondary brand colour: tints the sidebar, active nav and secondary accents so the second colour is visible across the app. */
.app-shell .sidebar { background: linear-gradient(180deg, color-mix(in srgb, var(--brand-secondary,#1e3a8a) 38%, #14171b), color-mix(in srgb, var(--brand-secondary,#1e3a8a) 18%, #101316)) !important; border-color: color-mix(in srgb, var(--brand-secondary,#1e3a8a) 40%, #2a2d31) !important; }
