/* Live AI bot on task cards: the agent's own picture, with its original eyes moving */
.bot-live{--lx:0px;--ly:0px;--tx:0px;--ta:0deg;position:relative;display:inline-flex;flex:none;width:36px;height:36px}
.bot-body{position:relative;display:block;width:36px;height:36px}
.bot-body .avatar{width:36px!important;height:36px!important;min-width:36px;border-radius:0!important;background-color:transparent!important;box-shadow:none!important;border:0!important;background-size:contain!important;background-repeat:no-repeat!important;background-position:center!important}
.bot-pupil{position:absolute;max-width:none;transform:translate(calc(-50% + var(--lx)),calc(-50% + var(--ly)));pointer-events:none;transition:transform .07s linear;animation:bot-blink 4.6s infinite}
.bot-flat{display:block}
.bot-body{translate:var(--tx) 0;rotate:var(--ta);transition:translate .1s linear,rotate .1s linear}
.bot-mouth{position:absolute;width:20%;height:9%;transform:translateX(-50%);border-bottom:2px solid rgba(16,19,25,.9);border-radius:0 0 50px 50px;pointer-events:none}
.bot-live:not(.bot-ready) .bot-mouth{display:none}
/* To do: eager, bouncing with anticipation, wide eyes, big grin */
.bot-eager .bot-body{animation:bot-eager 1.6s ease-in-out infinite}
.bot-eager .bot-pupil{transform:translate(calc(-50% + var(--lx)),calc(-50% + var(--ly))) scale(1.15)}
