/* In progress: active, running on the spot, speed lines, panting mouth */
.bot-run .bot-body{animation:bot-run .38s ease-in-out infinite;transform-origin:50% 90%}
.bot-run .bot-mouth{width:12%;height:12%;border:2px solid rgba(16,19,25,.9);border-radius:50%;animation:bot-pant .38s ease-in-out infinite}
.bot-speed{position:absolute;left:-7px;top:8px;width:9px;height:18px;pointer-events:none}
