.bot-bored .bot-mouth{width:18%;height:0;border-bottom:2px solid rgba(16,19,25,.85);border-radius:0;transform:translateX(-50%) rotate(2deg)}
.bot-bubble{position:absolute;top:-7px;right:-4px;font-size:13px;font-weight:700;color:var(--brand-primary,#42baff);letter-spacing:1px;animation:bot-sigh 3.4s ease-in-out infinite;pointer-events:none}
/* Done: relaxed, slow breathing sway, content closed eyes, soft smile */
.bot-relax .bot-body{animation:bot-relax 4s ease-in-out infinite}
.bot-relax .bot-pupil{animation:none;transform:translate(-50%,-10%) scaleY(.3)}
.bot-relax .bot-mouth{width:20%;height:9%}
@keyframes bot-blink{0%,92%,100%{scale:1 1}95%{scale:1 .12}}
@keyframes bot-eager{0%,55%,100%{transform:translateY(0) scale(1)}62%{transform:translateY(-4px) scale(1.04)}70%{transform:translateY(0) scale(.97)}78%{transform:translateY(-2px)}86%{transform:translateY(0)}}
@keyframes bot-run{0%,100%{transform:translateY(0) rotate(5deg)}50%{transform:translateY(-3px) rotate(-1deg)}}
@keyframes bot-pant{0%,100%{transform:translateX(-50%) scale(.8)}50%{transform:translateX(-50%) scale(1.25)}}
@keyframes bot-streak{0%{opacity:0;transform:translateX(5px)}30%{opacity:.9}100%{opacity:0;transform:translateX(-6px)}}
@keyframes bot-droop{0%,100%{transform:rotate(0) translateY(0)}35%,65%{transform:rotate(-8deg) translateY(2px)}}
@keyframes bot-roll{0%,40%,100%{translate:0 0}50%{translate:.9px -1.2px}60%{translate:-.9px -1.2px}70%{translate:0 0}}
@keyframes bot-sigh{0%,100%{opacity:0;transform:translateY(2px)}40%,70%{opacity:1;transform:translateY(-2px)}}
@keyframes bot-relax{0%,100%{transform:translateY(0) rotate(-2deg) scale(1)}50%{transform:translateY(1px) rotate(2deg) scale(1.04)}}
@media (prefers-reduced-motion:reduce){.bot-live,.bot-live *{animation:none!important}}
.pipeline-card-drag-preview .bot-live{animation:bot-spin .9s ease-in-out infinite!important}
@keyframes bot-spin{0%{transform:rotate(0)}60%,100%{transform:rotate(360deg)}}
/* Scrolling over a column scrolls it first, then hands off to the page when it reaches the end */
.app-shell .crm-kanban .crm-stage, .app-shell .pipeline-board .pipeline-column, .app-shell .pipeline-board .pipeline-column * { overscroll-behavior-y: auto; }
.app-shell .pipeline-card, .app-shell .pipeline-card * { touch-action: pan-y; }
.app-shell .pipeline-card[draggable="true"] { touch-action: pan-y; }

/* Smooth card dragging: pause every bot animation on the board while a card is lifted, keep the lifted copy spinning. */
body.task-card-drag-active .bot-live:not(.pipeline-card-drag-preview .bot-live),
body.task-card-drag-active .bot-live:not(.pipeline-card-drag-preview .bot-live) * { animation-play-state: paused !important; }
.pipeline-card-drag-preview, .pipeline-card-drag-preview * { transition: none !important; }
.pipeline-card-drag-preview { will-change: transform; }
